<?php
declare(strict_types=1);

/*
 * Baseline for Settings > Tests: the tests performed while this dashboard was built, with results and fixes.
 * It is copied into the database once (and again whenever 'version' is raised). New entries are added in the interface.
 * result: pass = passed first time, fixed = a problem was found and fixed, open = known gap or action still needed, info = note.
 */
$d = '2026-11-09';
$e = [];
$add = static function (string $ref, string $area, string $test, string $result, string $details, string $fix = '') use (&$e, $d): void {
    $e[] = ['ref' => $ref, 'date' => $d, 'area' => $area, 'test' => $test, 'result' => $result, 'details' => $details, 'fix' => $fix];
};

